import * as React from 'react';
import * as ToastPrimitive from '@radix-ui/react-toast';
import { ToastTypes, PositionType } from './Toast.types';
import {
  StyledBottomLeftViewport,
  StyledBottomRightViewport,
  StyledTopLeftViewport,
  StyledTopRightViewport,
  StyledToast,
  StyledTopViewport,
  StyledBottomViewport,
} from './Toast.styles';
import { Alert } from '../alert';

// Exports
export const ToastProvider = ToastPrimitive.Provider;
export const TopRightViewport = StyledTopRightViewport;
export const TopLeftViewport = StyledTopLeftViewport;
export const BottomLeftViewport = StyledBottomLeftViewport;
export const BottomRightViewport = StyledBottomRightViewport;
export const TopViewport = StyledTopViewport;
export const BottomViewport = StyledBottomViewport;
export const ToastClose = ToastPrimitive.Close;

type ViewPortProps = {
  position: PositionType;
};

const ViewPort = ({ position }: ViewPortProps) => {
  switch (position) {
    case 'top':
      return <TopViewport />;
    case 'top-right':
      return <TopRightViewport />;
    case 'top-left':
      return <TopLeftViewport />;
    case 'bottom':
      return <BottomViewport />;
    case 'bottom-right':
      return <BottomRightViewport />;
    case 'bottom-left':
      return <BottomLeftViewport />;
    default:
      return <TopRightViewport />;
  }
};

export const Toast = (props: ToastTypes): JSX.Element => {
  const {
    position,
    type,
    message,
    actions,
    onClose,
    showCloseButton,
    open,
    onOpenChange,
    ...rest
  } = props;

  return (
    <>
      <StyledToast open={open} onOpenChange={onOpenChange}>
        <Alert
          message={message}
          type={type}
          actions={actions}
          onClose={onClose}
          showCloseButton={showCloseButton}
          {...rest}
        />
      </StyledToast>
      <ViewPort position={position} />
    </>
  );
};
